{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C59"],
      "claim": "Probenecid, a sulfamoylbenzoic acid with a carboxylic acid, has ~100% oral bioavailability in humans, directly supporting high F for the query's sulfamoylbenzoic acid core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Salicylate has essentially complete systemic availability after oral dosing in humans, supporting high F for an aromatic carboxylic acid-containing molecule like the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Vorinostat, a polar aromatic molecule with ionizable groups, has 43% oral bioavailability in fasting humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Pethidine, a basic amine-containing drug, has absolute oral bioavailability around 53% in healthy volunteers, supporting high F for the query's basic pyrrolidine feature.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Solifenacin, a lipophilic basic amine drug, has 88% absolute oral bioavailability in healthy adults, supporting high F for the query's basic amine and aromatic ether features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Encainide, an anilide with a basic amine, has 20-30% oral bioavailability in healthy subjects, still at or above the threshold and consistent with a high prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Levothyroxine, a polar amino acid with diaryl ether and phenolic groups, has about 84% oral bioavailability in a patient study, supporting high F for the query's polar and ether-containing scaffold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All highly transferable experimental analogues show oral bioavailability at or above the 20% threshold, mostly 40-100%. The query's sulfamoylbenzoic acid, phenoxy, and pyrrolidine features align with high-F drugs such as probenecid and related loop diuretics, so the prediction is high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is present in the evidence set.",
    "No specific data on intestinal permeability, efflux transport, or first-pass metabolism for the exact query structure are provided.",
    "The zwitterionic potential of the query could modulate absorption, but consistent high-F analogues outweigh this uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

